// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testRegression_property() public {
        address ownerBefore = c.owner();
        vm.prank(ownerBefore);
        c.transferOwnership(address(1));

        vm.prank(address(1));
        (bool ok, ) = address(c).call(abi.encodeWithSignature("owned()"));
        assertTrue(ok);
    }
}
